package ru.fifth.horror.item;import net.minecraft.item.Item;import net.minecraft.item.ItemUsageContext;import net.minecraft.util.ActionResult;import net.minecraft.util.math.Direction;import ru.fifth.horror.FifthMod;import ru.fifth.horror.entity.LiftPanelEntity;
public final class LiftPanelItem extends Item{public LiftPanelItem(Settings s){super(s);}@Override public ActionResult useOnBlock(ItemUsageContext c){if(c.getWorld().isClient)return ActionResult.SUCCESS;LiftPanelEntity e=new LiftPanelEntity(FifthMod.LIFT_PANEL,c.getWorld());var hit=c.getHitPos();Direction side=c.getSide();double eps=.015;e.setPosition(hit.x+side.getOffsetX()*eps,hit.y+side.getOffsetY()*eps,hit.z+side.getOffsetZ()*eps);e.setYaw(switch(side){case NORTH->180;case SOUTH->0;case WEST->90;case EAST->-90;default->0;});c.getWorld().spawnEntity(e);if(c.getPlayer()!=null&&!c.getPlayer().getAbilities().creativeMode)c.getStack().decrement(1);return ActionResult.SUCCESS;}}
